const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='nlp-learning-v1';
function lessonSearchText(l){
  const prose=[l.title,l.subtitle,l.goal,l.summary,...l.tags,...l.sections.flat(),...l.exercise,l.answer,...l.quiz.flat()];
  return (prose.join(' ').replace(/<[^>]*>/g,' ')+' '+(l.code||'')).normalize('NFKC').toLowerCase();
}
function bindDownloads(){
  document.querySelectorAll('[data-download]').forEach(button=>button.onclick=()=>{
    const name=button.dataset.download;
    if(!Object.prototype.hasOwnProperty.call(EXAMPLE_FILES,name))return;
    const url=URL.createObjectURL(new Blob([EXAMPLE_FILES[name]],{type:'text/plain;charset=utf-8'}));
    const link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();
    setTimeout(()=>URL.revokeObjectURL(url),10000);
  });
}
function cleanPrintDocument(){
  document.getElementById('print-document')?.remove();
  document.body.classList.remove('print-all');
}
function preparePrintDocument(){
  cleanPrintDocument();
  const output=document.createElement('div');output.id='print-document';
  output.innerHTML='<p class="print-intro">NLP Learning Lab · 実験は各章の初期設定で計算した結果です。</p>'+home()+fieldsPage()+LESSONS.map((_,i)=>lesson(i,true)).join('');
  output.querySelectorAll('.lesson').forEach((root,i)=>initLab(LESSONS[i].lab,root,false));
  output.querySelectorAll('details').forEach(el=>el.open=true);
  output.querySelectorAll('.quiz .answer').forEach(button=>{
    const choice=document.createElement('div');choice.className='print-choice';choice.textContent=button.textContent;button.replaceWith(choice);
  });
  output.querySelectorAll('.lab input,.lab select,.lab textarea').forEach(input=>{
    const value=document.createElement('div');value.className='print-value';
    value.textContent=input.tagName==='SELECT'?input.selectedOptions[0].textContent:input.value;
    input.replaceWith(value);
  });
  output.querySelectorAll('button,.download-actions,.map-tools').forEach(el=>el.remove());
  // 各章の同名IDが画面側と衝突しないよう、計算後の印刷用要素から除きます。
  output.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));
  output.querySelectorAll('[for]').forEach(el=>el.removeAttribute('for'));
  output.querySelectorAll('.field-page .sources').forEach(el=>el.insertAdjacentHTML('beforebegin','<p class="print-only">学習メモと進捗は印刷に含まれません。</p>'));
  document.body.appendChild(output);document.body.classList.add('print-all');
  return output;
}
let state={done:[],notes:{}};
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Array.isArray(saved.done)&&saved.notes&&typeof saved.notes==='object')state=saved;}catch{}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{return false;}}
function softmax(xs,t=1){const m=Math.max(...xs);const es=xs.map(x=>Math.exp((x-m)/t));const total=es.reduce((a,b)=>a+b,0);return es.map(x=>x/total);}
function bars(labels,values,scale=1){return `<div class="bars">${labels.map((l,i)=>`<div class="barrow"><span>${esc(l)}</span><div class="bartrack"><div class="barfill" style="width:${Math.max(0,Math.min(100,values[i]/scale*100))}%"></div></div><span>${values[i].toFixed(3)}</span></div>`).join('')}</div>`;}
function nav(){const query=$('#search').value.normalize('NFKC').trim().toLowerCase();const active=location.hash;$('#nav').innerHTML=`<a class="navitem ${active==='#home'||!active?'active':''}" href="#home"><span class="num">⌂</span>学習マップ</a><a class="navitem ${active==='#fields'?'active':''}" href="#fields"><span class="num">◇</span>NLPの分野マップ</a>`+LESSONS.map((l,i)=>({l,i})).filter(({l})=>lessonSearchText(l).includes(query)).map(({l,i})=>`<a class="navitem ${active===`#chapter-${i+1}`?'active':''} ${state.done.includes(i)?'done':''}" href="#chapter-${i+1}" ${active===`#chapter-${i+1}`?'aria-current="page"':''}><span class="num">${state.done.includes(i)?'✓':String(i+1).padStart(2,'0')}</span>${l.title}</a>`).join('');if(query&&$('#nav').children.length===2)$('#nav').insertAdjacentHTML('beforeend','<p class="empty">該当する章がありません。</p>');$('#count').textContent=`${state.done.length} / 12`;$('#progress').value=state.done.length;}
function home(){return `<div class="home"><div class="hero"><div><p class="eyebrow">Python経験者向け</p><h1>自然言語処理入門</h1><p class="lead">テキストの数値化から、分類・Transformer・RAGまでを、<br>図解と小さな実験で順に学びます。</p><a class="primary" href="#chapter-1">第1章から始める <span aria-hidden="true">↗</span></a></div><div class="hero-visual" aria-label="文章からトークン、ベクトル、予測への変換の図"><div class="visual-label">FROM WORDS TO NUMBERS</div><div class="sentence">「猫が好き」</div><div class="tokenrow"><span class="token">猫</span><span class="token">が</span><span class="token">好き</span></div><div class="arrow">↓</div><div class="vectorrow">${[0,1,2].map((v)=>`<div class="vector">${[18,28,11,34,22,15].map((h,i)=>`<i style="height:${(h+v*7+i*3)%30+8}px"></i>`).join('')}</div>`).join('')}</div><div class="arrow">↓</div><div class="output">数値表現を使って、分類・検索・生成を行う</div><small style="display:block;text-align:center;color:var(--muted);font-size:10px;margin-top:12px">概念図 · ベクトルは説明用です</small></div></div><div class="facts"><div><b>12</b><span>基礎から応用までの章</span></div><div><b>12</b><span>ブラウザで動かす実験</span></div><div><b>Python</b><span>基本文法の経験が前提</span></div></div><a class="field-teaser" href="#fields"><span>まずは全体像から</span><b>NLPには、どんな分野がある？</b><small>手法の4段階と応用 × 解く問題の地図 →</small></a><div class="sectionhead"><h2>学習マップ</h2><small>全12章を4つの段階に分けています。</small></div>${[['01','基礎','ことばと数値',0,3],['02','分類と評価','表現と評価',3,6],['03','系列モデル','系列とAttention',6,9],['04','応用','LLMと実験',9,12]].map(([n,t,s,start,end])=>`<section class="phase"><div class="phase-label">PHASE ${n}<b>${t}</b>${s}</div><div class="cards">${LESSONS.slice(start,end).map((l,j)=>`<a class="chaptercard" href="#chapter-${start+j+1}"><span class="index">${String(start+j+1).padStart(2,'0')} ${state.done.includes(start+j)?'✓':''}</span><h3>${l.title}</h3><p>${l.subtitle}</p><small>学習時間の目安 ${l.time}分 <span aria-hidden="true">↗</span></small></a>`).join('')}</div></section>`).join('')}<div class="guide"><h3>学習の進め方（3ステップ）</h3><p><b>1. 図から入る。</b> 入力・出力・数式の形を確認する。</p><p><b>2. 変えてみる。</b> 実験の数値を動かし、結果を予想してから見る。</p><p><b>3. 説明して残す。</b> 理解チェックと演習に答え、メモに自分の説明を書く。</p><p>各章の時間は初めて学ぶ場合の学習時間の目安です。Pythonの実行は別の環境で行います。最終課題には追加の実装時間を取りましょう。</p></div><div class="sectionhead"><h2>4週間の進め方</h2><small>週3回＋復習。ペースは自由です。</small></div><div class="schedule">${['1〜3章：全体像・数学・前処理','4〜6章：TF-IDF・評価・埋め込み','7〜9章：系列・Attention・Transformer','10〜12章：LLM・RAG・最終課題'].map((x,i)=>`<div><b>Week ${i+1}</b>${x}<br>章を読む → 演習 → 復習</div>`).join('')}</div><div class="sectionhead"><h2>深く学ぶための参考資料</h2></div><div class="sources"><p>教材は独自の入門解説です。詳細や実装仕様は各章の参考資料で確認できます。</p>${['slp','hf','attention','tfidf'].map(k=>`<a href="${SOURCES[k][1]}" target="_blank" rel="noopener">${SOURCES[k][0]} ↗</a>`).join('')}</div></div>`;}
function lesson(i,print=false){const l=LESSONS[i];return `<article class="lesson" data-chapter="${i}"><div class="lesson-nav"><a href="#home">学習マップ</a> / 第${i+1}章</div><p class="eyebrow">CHAPTER ${String(i+1).padStart(2,'0')} / 12 · 学習時間の目安 ${l.time}分</p><h1>${l.title}</h1><p class="summary">${l.summary}</p><div class="tags">${l.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="objectives"><b>この章のゴール</b><p>${l.goal}</p></div>${l.sections.map(([t,b],j)=>`<section><h2><span style="color:var(--green);font:14px ui-monospace;margin-right:10px">0${j+1}</span>${t}</h2>${b}</section>`).join('')}<div class="lab" id="lab-${i}"><span class="lab-heading">TRY IT YOURSELF</span>${labMarkup(l.lab)}</div>${l.code?`<div class="code-top"><span>Pythonで確かめる · 自分の環境で実行</span><button class="copy" data-i="${i}">コードをコピー</button></div><pre><code>${esc(l.code)}</code></pre>`:''}<div class="quiz"><h3>理解チェック</h3><p>${l.quiz[0]}</p>${l.quiz[1].map((x,j)=>`<button class="answer" data-i="${i}" data-answer="${j}">${String.fromCharCode(65+j)}. ${x}</button>`).join('')}<div class="feedback" role="status" aria-live="polite"></div><div class="print-only">正解：${l.quiz[1][l.quiz[2]]}。${l.quiz[3]}</div></div><section class="exercise"><h3>自分の手で考える</h3><ol>${l.exercise.map(x=>`<li>${x}</li>`).join('')}</ol><details ${print?'open':''}><summary>解答の例を見る</summary><p>${l.answer}</p></details></section>${print?'':`<div class="memo"><label for="memo">学習メモ</label><textarea id="memo" placeholder="今日理解したこと、まだ疑問なこと、自分の言葉での説明…">${esc(state.notes[i]||'')}</textarea><small id="memo-status" aria-live="polite">このブラウザ内だけに保存します。別端末には同期されません。</small></div><div class="lesson-bottom"><a href="${i?`#chapter-${i}`:'#home'}">← ${i?'前の章':'学習マップ'}</a><button class="primary" id="complete">${state.done.includes(i)?'✓ 完了済み（取り消す）':'この章を完了にする'}</button><a href="${i<11?`#chapter-${i+2}`:'#home'}">${i<11?'次の章':'学習マップ'} →</a></div>`}<div class="sources"><b>参考資料</b>${l.sources.map(k=>`<a href="${SOURCES[k][1]}" target="_blank" rel="noopener">${SOURCES[k][0]} ↗</a>`).join('')}</div></article>`;}
function labMarkup(kind){switch(kind){
case 'task':return '<h3>タスクを選び、入力と出力を確認</h3><label for="task">目的</label><select id="task"><option value="0">感情分類</option><option value="1">固有表現抽出</option><option value="2">文書検索</option><option value="3">翻訳</option></select><div class="labresult" id="result" aria-live="polite"></div>';
case 'softmax':case 'sampling':return `<h3>${kind==='sampling'?'温度を変えて、次トークンの分布を見る':'同じスコアでも、温度で確率は変わる'}</h3><p>候補「猫・犬・鳥」の架空のlogitは [2, 1, 0]。</p><label for="temperature">温度 T：<output id="temp-value">1.00</output></label><input id="temperature" type="range" min="0.1" max="3" step="0.05" value="1"><div class="labresult" id="result" aria-live="polite"></div>${kind==='sampling'?'<button id="sample">分布から1つ抽選する</button><span id="sampled" role="status"></span>':''}`;
case 'tokenize':return '<h3>同じ文章を、異なる単位で分割</h3><label for="text">文章（最大200文字）</label><input id="text" maxlength="200" value="ＡＩ について学ぶ"><label for="unit">分割単位</label><select id="unit"><option value="char">文字単位</option><option value="space">空白単位</option></select><p>これは分割の基本を観察する実験です。日本語の形態素解析・BPEは実行していません。</p><div class="labresult" id="result" aria-live="polite"></div>';
case 'tfidf':return '<h3>コーパスを変えて、IDFを確かめる</h3><label for="docs">1行1文書・語は空白区切り（最大2,000文字）</label><textarea id="docs" rows="3" maxlength="2000">猫 好き\n犬 好き\n猫 猫</textarea><p>TFは出現回数、IDFは平滑化あり、L2正規化なし。先頭20語を表示します。</p><div class="labresult" id="result" aria-live="polite"></div>';
case 'metrics':return '<h3>誤検出と見逃しで、何が変わる？</h3><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px">'+['TP','FP','FN','TN'].map((x,i)=>`<label>${x}<input class="cm" type="number" min="0" max="10000" step="1" value="${[8,2,4,86][i]}" aria-label="${x}"></label>`).join('')+'</div><div class="labresult" id="result" aria-live="polite"></div>';
case 'embedding':return '<h3>2本のベクトルの、角度を変える</h3><p>赤は [1,0]、緑は [cosθ,sinθ]。意味を学習したベクトルではなく、方向を理解する幾何学デモです。</p><label for="angle">角度 θ：<output id="angle-value">45°</output></label><input id="angle" type="range" min="0" max="180" value="45"><div class="labresult" id="result" aria-live="polite"></div>';
case 'bigram':return '<h3>直前の1語で予測する</h3><p>架空の学習カウントに基づく、平滑化なしのbigramです。文頭・文末は省略しています。</p><label for="previous">直前の語</label><select id="previous"><option>猫</option><option>が</option><option>好き</option></select><div class="labresult" id="result" aria-live="polite"></div>';
case 'attention':return '<h3>重みが変わると、混ぜる内容も変わる</h3><p>1つのQueryに対する、スケーリング後の架空スコアを変更。各Valueは [1,0]・[0,2]・[2,2]。</p>'+['私','猫','好き'].map((t,i)=>`<label for="score-${i}">${t} のスコア：<output id="score-value-${i}">${[1,2,0][i]}</output></label><input class="score" id="score-${i}" type="range" min="-3" max="3" step="0.1" value="${[1,2,0][i]}">`).join('')+'<div class="labresult" id="result" aria-live="polite"></div>';
case 'mask':return '<h3>どの位置が、どの位置を参照できる？</h3><label for="mask">マスク</label><select id="mask"><option value="causal">causal：過去と自分だけ</option><option value="full">全位置：双方向</option></select><p>行はQuery、列はKey。●は参照できる位置、—は参照できない位置です。</p><div class="labresult" id="result"></div>';
case 'rag':return '<h3>検索された根拠を確認する</h3><p>3件の架空の講座案内を対象にした文字2-gramのJaccard類似度検索。LLMによる回答生成は行いません。</p><label for="query">質問</label><input id="query" maxlength="200" value="講座の開催日は？"><div class="labresult" id="result" aria-live="polite"></div>';
case 'experiment':return '<h3>実験計画を組み立てる</h3><p>この欄は下の学習メモとは別です。計画をコピーして手元に保存できます。</p>'+[['purpose','入力 → 出力','レビュー → 肯定 / 否定'],['baseline','ベースライン','多数派予測、TF-IDF＋ロジスティック回帰'],['evaluation','評価・分割','macro F1、重複を除いた固定分割']].map(([id,t,v])=>`<label for="${id}">${t}</label><input id="${id}" maxlength="500" value="${v}">`).join('')+'<div class="labresult" id="result"></div><button id="copy-plan">計画をコピー</button><span id="plan-status" role="status"></span>';
}}
function initLab(kind, root=document, interactive=true){const $=s=>root.querySelector(s);const result=$('#result');const update=()=>{switch(kind){
case 'task':{const k=Number($('#task').value);result.innerHTML=[['レビュー：「とても面白かった」','出力：肯定','評価：F1・混同行列'],['文章：「田中さんは東京で働く」','出力：田中→人名、東京→地名','評価：範囲とラベルの一致'],['質問：「NLPの教材は？」','出力：関連文書を順位付きで返す','評価：Recall@k・MRR'],['原文：「猫が好きです」','出力：I like cats.','評価：自動指標と人による評価']][k].map(x=>`<div>${x}</div>`).join('');break;}
case 'softmax':case 'sampling':{const t=Number($('#temperature').value);$('#temp-value').value=t.toFixed(2);const ps=softmax([2,1,0],t);result.innerHTML=bars(['猫','犬','鳥'],ps)+`<p>合計：${ps.reduce((a,b)=>a+b,0).toFixed(3)}${kind==='softmax'?` / 正解が猫なら損失：${(-Math.log(ps[0])).toFixed(3)}`:''}</p>`;break;}
case 'tokenize':{const s=$('#text').value;const normalized=s.normalize('NFKC').replace(/\s+/g,' ').trim();const tokens=$('#unit').value==='char'?Array.from(normalized).filter(x=>!(/\s/.test(x))):normalized.split(/\s+/).filter(Boolean);result.innerHTML=`<p>正規化後：${esc(normalized)||'（空）'}</p><div class="tokenrow" style="justify-content:flex-start">${tokens.map(t=>`<span class="token">${esc(t)}</span>`).join('')}</div><p>${tokens.length} トークン${$('#unit').value==='char'?'（空白は除外）':''}</p>`;break;}
case 'tfidf':{const docs=$('#docs').value.split('\n').map(d=>d.trim().split(/\s+/).filter(Boolean)).filter(d=>d.length);if(!docs.length){result.textContent='文書を入力してください。';break;}const vocab=[...new Set(docs.flat())].slice(0,20);result.innerHTML=table(['語','df','IDF',...docs.map((_,i)=>`文書${i+1} TF-IDF`)],vocab.map(t=>{const df=docs.filter(d=>d.includes(t)).length;const idf=Math.log((docs.length+1)/(df+1))+1;return [esc(t),df,idf.toFixed(3),...docs.map(d=>(d.filter(x=>x===t).length*idf).toFixed(3))];}));break;}
case 'metrics':{const ns=[...root.querySelectorAll('.cm')].map(x=>Math.max(0,Math.min(10000,Math.floor(Number(x.value)||0))));const [tp,fp,fn,tn]=ns;const ratio=(a,b)=>b?a/b:null;const p=ratio(tp,tp+fp),r=ratio(tp,tp+fn),f=ratio(2*tp,2*tp+fp+fn),acc=ratio(tp+tn,tp+fp+fn+tn);result.innerHTML='<div class="metrics">'+[[p,'Precision'],[r,'Recall'],[f,'F1'],[acc,'Accuracy']].map(([v,t])=>`<div class="metric">${v===null?'未定義':v.toFixed(3)}<small>${t}</small></div>`).join('')+'</div><p>分母0は「未定義」と表示。入力は0〜10,000の整数として扱います。</p>';break;}
case 'embedding':{const a=Number($('#angle').value),x=Math.cos(a*Math.PI/180),y=Math.sin(a*Math.PI/180);$('#angle-value').value=`${a}°`;result.innerHTML=`<svg viewBox="0 0 360 200" width="360" role="img" aria-label="角度${a}度の単位ベクトル"><line x1="25" y1="170" x2="335" y2="170" stroke="#b4c3aa"/><line x1="180" y1="190" x2="180" y2="15" stroke="#b4c3aa"/><path d="M 60 170 A 120 120 0 0 1 300 170" fill="none" stroke="#d8e0d0" stroke-dasharray="4 4"/><line x1="180" y1="170" x2="300" y2="170" stroke="#c57544" stroke-width="4"/><line x1="180" y1="170" x2="${180+120*x}" y2="${170-120*y}" stroke="#196b54" stroke-width="4"/><circle cx="${180+120*x}" cy="${170-120*y}" r="5" fill="#196b54"/></svg><p>緑のベクトル：[${x.toFixed(3)}, ${y.toFixed(3)}] / コサイン類似度：<b>${x.toFixed(3)}</b></p>`;break;}
case 'bigram':{const k=$('#previous').value;const data={'猫':[['が','は'],[3,1]],'が':[['好き','走る'],[2,2]],'好き':[['です','だ'],[4,1]]};const [ls,cs]=data[k];result.innerHTML=`<p>「${k}」の後のカウント：${ls.map((l,i)=>`${l}=${cs[i]}`).join('、')}</p>`+bars(ls,cs.map(c=>c/cs.reduce((a,b)=>a+b,0)));break;}
case 'attention':{const scores=[...root.querySelectorAll('.score')].map((x,i)=>{const v=Number(x.value);$(`#score-value-${i}`).value=v.toFixed(1);return v;});const w=softmax(scores),v=[[1,0],[0,2],[2,2]],out=[0,1].map(j=>w.reduce((s,a,i)=>s+a*v[i][j],0));result.innerHTML=bars(['私','猫','好き'],w)+`<p>重みの合計：1.000 / 出力 = [${out.map(x=>x.toFixed(3)).join(', ')}]</p>`;break;}
case 'mask':{const full=$('#mask').value==='full';result.innerHTML=table(['Query ↓ / Key →','1','2','3','4','5'],Array.from({length:5},(_,i)=>[i+1,...Array.from({length:5},(_,j)=>full||j<=i?'●':'—')]));break;}
case 'rag':{const docs=['講座の開催日は11月1日です。','講座の参加費は無料です。','講座の場所はオンラインです。'];const grams=s=>{const a=Array.from(s.replace(/[\s？?。、]/g,''));return new Set(a.slice(0,-1).map((c,i)=>c+a[i+1]));};const q=grams($('#query').value);const ranked=docs.map((d,i)=>{const g=grams(d);const intersection=[...q].filter(t=>g.has(t)).length;const union=new Set([...q,...g]).size;return {d,i,score:union?intersection/union:0};}).sort((a,b)=>b.score-a.score);result.innerHTML=ranked.map((r,i)=>`<p><b>${i+1}位 · 文書${r.i+1}</b> / 類似度 ${r.score.toFixed(3)}<br>${esc(r.d)}</p>`).join('')+'<p>スコアは回答の確かさではありません。関係がない質問でも候補が並ぶので、根拠の有無を確認します。</p>';break;}
case 'experiment':{result.textContent=`入力・出力：${$('#purpose').value}\nベースライン：${$('#baseline').value}\n評価・分割：${$('#evaluation').value}`;result.style.whiteSpace='pre-wrap';break;}
}};update();if(!interactive)return;root.querySelectorAll('.lab input,.lab select,.lab textarea').forEach(el=>el.addEventListener('input',update));if(kind==='sampling')$('#sample').onclick=()=>{const ps=softmax([2,1,0],Number($('#temperature').value)),r=Math.random();let sum=0,index=2;for(let j=0;j<ps.length;j++){sum+=ps[j];if(r<sum){index=j;break;}}$('#sampled').textContent=` → 抽選結果：${['猫','犬','鳥'][index]}`;};if(kind==='experiment')$('#copy-plan').onclick=()=>copyText(result.textContent,$('#plan-status'));}
async function copyText(text,target){try{await navigator.clipboard.writeText(text);target.textContent='コピーしました';}catch{target.textContent='コピーできません。表示された本文を選択してコピーしてください。';}}
function render(focus=false){nav();const match=location.hash.match(/^#chapter-(\d+)$/);const i=match?Number(match[1])-1:-1;if(location.hash==='#fields'){$('#main').innerHTML=fieldsPage();document.title='NLPの分野マップ｜NLP Learning Lab';initFields();}else if(i<0||i>=LESSONS.length){$('#main').innerHTML=home();document.title='自然言語処理入門｜NLP Learning Lab';}else{const l=LESSONS[i];$('#main').innerHTML=lesson(i);document.title=`第${i+1}章 ${l.title}｜NLP Learning Lab`;initLab(l.lab);$('#complete').onclick=()=>{state.done=state.done.includes(i)?state.done.filter(v=>v!==i):[...state.done,i];const stored=save();nav();$('#complete').textContent=state.done.includes(i)?'✓ 完了済み（取り消す）':'この章を完了にする';if(!stored)$('#memo-status').textContent='ブラウザ保存が使えないため、再読込すると進捗が消えます。';};$('#memo').oninput=()=>{state.notes[i]=$('#memo').value;$('#memo-status').textContent=save()?'メモをこのブラウザに保存しました。':'保存できません。メモをコピーして手元に残してください。';};document.querySelectorAll('.answer').forEach(btn=>btn.onclick=()=>{const selected=Number(btn.dataset.answer),correct=selected===l.quiz[2];btn.closest('.quiz').querySelectorAll('button').forEach(b=>b.classList.remove('correct','wrong'));btn.classList.add(correct?'correct':'wrong');$('.feedback').textContent=(correct?'正解です。':'もう一度考えてみましょう。')+' '+l.quiz[3];});if(l.code)$('.copy').onclick=()=>copyText(l.code,$('.copy'));bindDownloads();}if(focus){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}}
$('#search').oninput=nav;
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();};
window.addEventListener('hashchange',()=>render(true));
$('#print').onclick=()=>{preparePrintDocument();window.print();};
window.addEventListener('afterprint',cleanPrintDocument);
render();
